const resp = $input.first().json;
const csrfToken = resp.body.data.csrfToken;
const setCookie = resp.headers['set-cookie'] || resp.headers['Set-Cookie'] || [];
const arr = Array.isArray(setCookie) ? setCookie : [setCookie];
const csrfCookie = arr.map(c => c.split(';')[0]).find(c => c.startsWith('ff_csrf='));
if (!csrfCookie) throw new Error('No ff_csrf cookie in /auth/csrf response - check apiBase');
return [{ json: { csrfToken, csrfCookie } }];

const resp = $input.first().json;
if (resp.statusCode >= 400) throw new Error('Login failed: ' + JSON.stringify(resp.body));
const setCookie = resp.headers['set-cookie'] || resp.headers['Set-Cookie'] || [];
const arr = Array.isArray(setCookie) ? setCookie : [setCookie];
const accessCookie = arr.map(c => c.split(';')[0]).find(c => c.startsWith('ff_access='));
if (!accessCookie) throw new Error('No ff_access cookie - login did not succeed');
const accessToken = accessCookie.split('=').slice(1).join('=');
return [{ json: { accessToken } }];

